"""Check saved lab6 part2 evidence and link the historical part1; no fault injection."""
from pathlib import Path
import hashlib,json

REPO=Path(__file__).resolve().parents[1];EV=REPO/'evidence/lab06-resources'
load=lambda name:json.loads((EV/(name+'.json')).read_text(encoding='utf-8'))
checks=[]
def check(name,value):checks.append({'name':name,'passed':bool(value)})
def actions(value):return [e['Action'] for e in value['events']]
initial=load('initial');oom=load('scenario-6-oom');db=load('scenario-7-db-unavailable')
bad=load('scenario-8-unhealthy');slow=load('scenario-9-slow-response');final=load('final-local')
check('Local current main image',initial['image']=='devops-labs-demo-api:lab12-2dd5a9f')
check('Initial API healthy and restart enabled',initial['state']['Health']['Status']=='healthy' and initial['restartPolicy']=='unless-stopped')
check('OOM limited to256MiB no extra swap',initial['memoryLimit']==initial['memorySwapLimit']==268435456)
check('Native leaks80and160MB returned',[(r['status'],r.get('body',{})) for r in oom['requests'][:2]]==[(200,{'leakedMb':80}),(200,{'leakedMb':160})])
check('OOM request connection interrupted',any(r['status'] is None and r.get('transportError') for r in oom['requests']))
check('Actual OOM event','oom' in actions(oom))
check('Actual exit137 event',any(e['Action']=='die' and e['Actor']['Attributes'].get('exitCode')=='137' for e in oom['events']))
check('OOM event order then die then start',actions(oom).index('oom')<actions(oom).index('die')<actions(oom).index('start'))
check('OOM restarts same container once',oom['before']['id']==oom['after']['id'] and oom['after']['restartCount']==oom['before']['restartCount']+1)
check('OOM recovered healthy',oom['after']['state']['Health']['Status']=='healthy')
check('OOMKilled reset after restart',oom['after']['state']['OOMKilled'] is False and oom['after']['state']['ExitCode']==0)
check('DB outage live200 ready503 data500',db['live']['status']==200 and db['ready']['status']==503 and db['tasks']['status']==500)
check('DB outage API remains healthy',db['after']['state']['Health']['Status']=='healthy')
check('DB outage no restart or recreation',db['before']['id']==db['after']['id'] and db['before']['restartCount']==db['after']['restartCount'] and db['before']['state']['StartedAt']==db['after']['state']['StartedAt'])
check('DB error logged',any(r.get('LogLevel')=='Error' and 'Npgsql' in r.get('Exception','') for r in db['logs']))
check('DB restored without API restart',load('db-restored')['inspection']['id']==db['before']['id'] and load('db-restored')['marker']['project']['status']==200)
check('Broken healthcheck targets nonexistent endpoint','no-such-endpoint' in str(bad['after']['healthcheck']))
check('Broken check unhealthy after40s',bad['after']['state']['Health']['Status']=='unhealthy' and bad['endNs']-bad['startNs']>=40_000_000_000)
check('Unhealthy event recorded','health_status: unhealthy' in actions(bad))
check('Failed health probes retained',any(r['ExitCode']!=0 and '404' in r['Output'] for r in bad['after']['state']['Health']['Log']))
check('Unhealthy still serves live and ready200',bad['live']['status']==200 and bad['ready']['status']==200)
check('Unhealthy does not restart',bad['before']['id']==bad['after']['id'] and bad['before']['restartCount']==bad['after']['restartCount']==0 and bad['before']['state']['StartedAt']==bad['after']['state']['StartedAt'])
check('Dependency and unhealthy no lifecycle restart events',all(not any(a in ['die','start','oom','kill','stop'] for a in actions(s)) for s in [db,bad]))
check('Slow response and normal request200',slow['normal']['status']==slow['delayed']['status']==200)
check('Slow3000ms actually measured',slow['delayed']['body']=={'delayedMs':3000} and slow['delayed']['seconds']>=2.9)
check('Slow response healthy without restart',slow['after']['state']['Health']['Status']=='healthy' and slow['before']['restartCount']==slow['after']['restartCount'] and not any(a in ['die','start','oom'] for a in actions(slow)))
check('Original compose restored',load('compose-restored')['exactBytesRestored'] and load('compose-restored')['originalSha256']==load('compose-restored')['finalSha256'])
check('Final live and ready200 healthy',final['live']['status']==final['ready']['status']==200 and final['inspection']['state']['Health']['Status']=='healthy')
marker=load('marker')
check('Marker preserved across all recoveries',all(s['marker']['project']['body']==marker['project'] and s['marker']['task']['body']==marker['task'] for s in [oom,load('db-restored'),final]))
check('Named PostgreSQL volume preserved',any(v.get('Name')=='devops-labs_pgdata' for v in final['dbVolumes']))
check('Original live healthcheck restored','/health/live' in str(final['inspection']['healthcheck']) and 'no-such-endpoint' not in str(final['inspection']['healthcheck']))
check('T2 stderr empty',(EV/'t2-stderr.txt').read_text().strip()=='')
check('T3 actual samples retained',load('resource-summary')['apiSamples']>10)
diag=load('diag-tests')
check('diag positive and negative paths checked',diag['healthyExitCode']==0 and diag['missingExitCode']!=0 and diag['missingContainerExplicitError'])
check('diag read-only identity preserved',diag['containerIdentityStartedAtRestartCountUnchanged'])
text=(EV/'diag-after-oom.txt').read_text(encoding='utf-8')
check('diag contains pastOOM and137 with reset current state','OOMKilled: False' in text and '"Action":"oom"' in text and '"exitCode":"137"' in text)
check('Historical scenarios2-5 exact source hashes',all(hashlib.sha256((REPO/r['path']).read_bytes()).hexdigest()==r['sha256'] for r in load('part1-references')['files']))
postman=load('postman-results')
check('Live Postman5requests11assertions',postman['requests']==5 and postman['assertions']==11 and postman['failed']==0 and postman['exitCode']==0)
result={'passed':sum(r['passed'] for r in checks),'failed':sum(not r['passed'] for r in checks),'checks':checks,
    'scope':'Retained real experiments6-9 and historical2-5, plus diag and Postman. Not a live status monitor.'}
(EV/'checks.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(str(result['passed'])+' passed; '+str(result['failed'])+' failed')
for row in checks:
    if not row['passed']:print('FAILED:',row['name'])
raise SystemExit(1 if result['failed'] else 0)
